// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // reference: non-admin caller triggers revert on setOwner, so state does not change
        // bug: non-admin caller does not revert, but assignment removed, so owner stays initial
        address nonAdmin = address(0x123);
        bool ok;
        vm.prank(nonAdmin);
        try c.setOwner(address(0x456)) { ok = true; } catch { ok = false; }
        // reference catches revert => ok == false, bug does not revert => ok == true
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address caller = address(0x1234);
        address newOwner = address(0xABCD);
        vm.prank(caller);
        c.setOwner(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        bool success;
        // Call setOwner from the default admin (the deployer, which is this contract)
        try c.setOwner(newOwner) { success = true; } catch { success = false; }
        assertTrue(success == true);
    }
}
